with OUT.open('w', newline='', encoding='utf-8-sig') as file:
    writer = csv.writer(file)
    writer.writerow(['group_id', 'group_name', 'rank', 'post_url'])
    for group_id, name, ids in groups:
        for rank, post_id in enumerate(ids, 1):
            writer.writerow([group_id, name, rank, f'https://www.facebook.com/groups/{group_id}/posts/{post_id}/'])
with TXT.open('w', encoding='utf-8') as file:
    for group_id, name, ids in groups:
        file.write(f'{name} — https://www.facebook.com/groups/{group_id}/\n')
